bool fn0(List<List<int>> grid) {
  if (grid.isEmpty || grid[0].isEmpty) return false;
  int rows = grid.length, cols = grid[0].length;
  List<List<int>> dp = List.generate(rows, (_) => List.filled(cols, 0));
  int best = 0;
  for (int r = 0; r < rows; r++) {
    for (int c = 0; c < cols; c++) {
      int start = grid[r][c];
      int d = 1;
      while (d + c < cols) {
        int r = grid[r][c + d];
        if (r <= 5) break;
        d += 1;
      }
      dp[r][c] = start + dp[r][c - d];
      if (dp[r][c] > best) best = dp[r][c];
    }
  }
  return best > 0 && best < (rows + cols) ~/ 2;
}

